// Mazmorras del Abismo: the dungeon dimension, its monsters and its key.
// Generated by tools/abismo.py (the dungeon is built by gen.js).
import { BlockPermutation, BlockVolume, ItemStack, system, world } from "@minecraft/server";
import { arenaAt, buildRegion, FLOORS, floorOf, inner0, regionOf, roomOf, roomType, SPAWN } from "./gen.js";

const CFG = {"dimension": "abismo:mazmorras", "key": "abismo:llave_del_abismo", "radius": 3, "opsPerStep": 48, "floorNames": ["Piso 1 · Salas Altas", "Piso 2 · Criptas", "Piso 3 · El Abismo"], "spawnInterval": 60, "spawnChance": 0.75, "cap": [6, 8, 10], "rarity": 1.4, "depth": 0.3, "mobs": [{"id": "minecraft:silverfish", "fuerza": 0.8, "grupo": [2, 4], "alto": 1}, {"id": "minecraft:zombie", "fuerza": 1.0, "grupo": [1, 3], "alto": 2}, {"id": "minecraft:zombie_villager_v2", "fuerza": 1.1, "grupo": [1, 1], "alto": 2}, {"id": "minecraft:husk", "fuerza": 1.2, "grupo": [1, 2], "alto": 2}, {"id": "minecraft:spider", "fuerza": 1.2, "grupo": [1, 2], "alto": 1}, {"id": "minecraft:skeleton", "fuerza": 1.3, "grupo": [1, 2], "alto": 2}, {"id": "minecraft:drowned", "fuerza": 1.5, "grupo": [1, 2], "alto": 2}, {"id": "minecraft:cave_spider", "fuerza": 1.5, "grupo": [1, 3], "alto": 1}, {"id": "minecraft:stray", "fuerza": 1.6, "grupo": [1, 2], "alto": 2}, {"id": "minecraft:slime", "fuerza": 1.8, "grupo": [1, 1], "alto": 2}, {"id": "minecraft:creeper", "fuerza": 2.2, "grupo": [1, 1], "alto": 2}, {"id": "minecraft:bogged", "fuerza": 2.2, "grupo": [1, 2], "alto": 2}, {"id": "minecraft:pillager", "fuerza": 2.8, "grupo": [1, 2], "alto": 2}, {"id": "minecraft:witch", "fuerza": 3.0, "grupo": [1, 1], "alto": 2}, {"id": "minecraft:magma_cube", "fuerza": 3.0, "grupo": [1, 1], "alto": 2}, {"id": "minecraft:vindicator", "fuerza": 4.0, "grupo": [1, 2], "alto": 2}, {"id": "minecraft:blaze", "fuerza": 4.0, "grupo": [1, 1], "alto": 2}, {"id": "minecraft:wither_skeleton", "fuerza": 5.0, "grupo": [1, 2], "alto": 3}, {"id": "minecraft:breeze", "fuerza": 5.5, "grupo": [1, 1], "alto": 2}, {"id": "minecraft:zoglin", "fuerza": 6.0, "grupo": [1, 1], "alto": 2}, {"id": "minecraft:piglin_brute", "fuerza": 6.5, "grupo": [1, 1], "alto": 2}, {"id": "minecraft:evoker", "fuerza": 7.5, "grupo": [1, 1], "alto": 2}, {"id": "abismo:arana_mutante", "fuerza": 8.0, "grupo": [1, 1], "alto": 2}, {"id": "minecraft:ravager", "fuerza": 9.0, "grupo": [1, 1], "alto": 3}, {"id": "abismo:zombi_mutante", "fuerza": 10.0, "grupo": [1, 1], "alto": 3}, {"id": "abismo:esqueleto_mutante_abisal", "fuerza": 11.0, "grupo": [1, 1], "alto": 4}, {"id": "abismo:creeper_mutante", "fuerza": 12.0, "grupo": [1, 1], "alto": 3}, {"id": "minecraft:warden", "fuerza": 22.0, "grupo": [1, 1], "alto": 3}], "ids": {"zombi": "abismo:zombi_mutante", "arana": "abismo:arana_mutante", "creeper": "abismo:creeper_mutante", "esqueleto": "abismo:esqueleto_mutante_abisal", "boss": "abismo:coloso_abisal"}, "slam": {"zombi": 9, "boss": 14}, "blast": 3.5, "minions": ["minecraft:zombie", "minecraft:skeleton", "minecraft:husk", "minecraft:wither_skeleton"], "bossChest": [["minecraft:diamond", 6], ["minecraft:echo_shard", 3], ["minecraft:netherite_scrap", 2], ["minecraft:enchanted_golden_apple", 1], ["minecraft:experience_bottle", 16], ["minecraft:disc_fragment_5", 4]]};
const DIM = CFG.dimension;
const MOB_TAG = "abismo_mob";

system.beforeEvents.startup.subscribe((ev) => {
  ev.dimensionRegistry.registerCustomDimension(DIM);
});

const abismo = () => world.getDimension(DIM);
const now = () => system.currentTick;

function seed() {
  let s = world.getDynamicProperty("abismo:seed");
  if (typeof s !== "number") {
    s = Math.floor(Math.random() * 2147483647);
    world.setDynamicProperty("abismo:seed", s);
  }
  return s;
}

function later(ticks, fn) {
  system.runTimeout(() => {
    try {
      fn();
    } catch {}
  }, ticks);
}

// ------------------------------------------------------------ generation
const perms = new Map();
function perm(block) {
  const id = typeof block === "string" ? block : block.id;
  const key = typeof block === "string" ? block : `${id}|${JSON.stringify(block.states)}`;
  if (!perms.has(key)) {
    let p = null;
    try {
      p = BlockPermutation.resolve(id, typeof block === "string" ? undefined : block.states);
    } catch {
      try {
        p = BlockPermutation.resolve(id);
      } catch {
        console.warn(`[ABISMO] bloque desconocido: ${key}`);
      }
    }
    perms.set(key, p);
  }
  return perms.get(key);
}

function fillChest(block, items) {
  const inv = block?.getComponent("minecraft:inventory")?.container;
  if (!inv) return;
  for (const [id, count] of items) {
    try {
      inv.addItem(new ItemStack(id, count));
    } catch {}
  }
}

function apply(dim, op) {
  if (op[0] === "f") {
    const [, x1, y1, z1, x2, y2, z2, b] = op;
    const p = perm(b);
    if (!p) return;
    if (x1 === x2 && y1 === y2 && z1 === z2) dim.getBlock({ x: x1, y: y1, z: z1 })?.setPermutation(p);
    else dim.fillBlocks(new BlockVolume({ x: x1, y: y1, z: z1 }, { x: x2, y: y2, z: z2 }), p);
    return;
  }
  const [, x, y, z, b, items] = op;
  const p = perm(b);
  const block = p && dim.getBlock({ x, y, z });
  if (!block) return;
  block.setPermutation(p);
  if (op[0] === "c") fillChest(block, items);
}

function* applyAll(dim, ops, done) {
  let n = 0;
  for (const op of ops) {
    try {
      apply(dim, op);
    } catch {}
    if (++n % CFG.opsPerStep === 0) yield;
  }
  done();
}

const regionKey = (gx, gz) => `abismo:region:${gx}:${gz}`;
const isBuilt = (gx, gz) => world.getDynamicProperty(regionKey(gx, gz)) === true;
const building = new Map();
const retryAt = new Map();
const areaId = (...parts) => `abismo_${parts.join("_")}`.replace(/-/g, "m");

async function loadArea(dim, id, from, to) {
  try {
    await world.tickingAreaManager.createTickingArea(id, { dimension: dim, from, to });
    return true;
  } catch (e) {
    console.warn(`[ABISMO] no se pudo crear la zona de carga ${id}: ${e}`);
    return false;
  }
}

function dropArea(id) {
  try {
    world.tickingAreaManager.removeTickingArea(id);
  } catch {}
}

function generateRegion(gx, gz) {
  const key = regionKey(gx, gz);
  if (isBuilt(gx, gz)) return Promise.resolve(true);
  if (building.has(key)) return building.get(key);
  const job = (async () => {
    const dim = abismo();
    const { ops, bounds } = buildRegion(gx, gz, seed());
    const [x0, z0, x1, z1] = bounds;
    const id = areaId("gen", gx, gz);
    const loaded = await loadArea(dim, id, { x: x0, y: 0, z: z0 }, { x: x1, y: 0, z: z1 });
    if (!loaded && (!dim.getBlock({ x: x0, y: 64, z: z0 }) || !dim.getBlock({ x: x1, y: 64, z: z1 }))) {
      retryAt.set(key, now() + 200);
      return false;
    }
    await new Promise((resolve) => system.runJob(applyAll(dim, ops, resolve)));
    world.setDynamicProperty(key, true);
    if (loaded) dropArea(id);
    return true;
  })();
  building.set(key, job);
  job.catch((e) => console.warn(`[ABISMO] error generando ${gx},${gz}: ${e}`)).finally(() => building.delete(key));
  return job;
}

const playersHere = () => world.getPlayers().filter((p) => p.dimension.id === DIM);

let busy = false;
system.runInterval(() => {
  if (busy) return;
  let best = null;
  for (const player of playersHere()) {
    const prx = roomOf(player.location.x), prz = roomOf(player.location.z);
    for (let dx = -CFG.radius; dx <= CFG.radius; dx++)
      for (let dz = -CFG.radius; dz <= CFG.radius; dz++) {
        const gx = regionOf(prx + dx), gz = regionOf(prz + dz);
        if (isBuilt(gx, gz) || (retryAt.get(regionKey(gx, gz)) ?? 0) > now()) continue;
        const d = dx * dx + dz * dz;
        if (!best || d < best.d) best = { gx, gz, d };
      }
  }
  if (!best) return;
  busy = true;
  generateRegion(best.gx, best.gz).finally(() => (busy = false));
}, 20);

// ------------------------------------------------------------ monsters
// The stronger the monster, the rarer: weight = 100 * strength^(-rarity + depth * floor).
const weights = [0, 1, 2].map((f) => CFG.mobs.map((m) => [m, 100 * Math.pow(m.fuerza, -CFG.rarity + CFG.depth * f)]));

function pickMob(f) {
  const list = weights[f];
  let total = 0;
  for (const [, w] of list) total += w;
  let k = Math.random() * total;
  for (const [m, w] of list) if ((k -= w) < 0) return m;
  return list[0][0];
}

const isMob = (e) => !["minecraft:player", "minecraft:armor_stand"].includes(e.typeId) &&
  e.getComponent("minecraft:health") !== undefined;

function airColumn(dim, x, y, z, h) {
  for (let i = 0; i < h; i++) {
    const b = dim.getBlock({ x, y: y + i, z });
    if (!b || !b.isAir) return false;
  }
  const below = dim.getBlock({ x, y: y - 1, z });
  return !!below && !below.isAir && !below.isLiquid;
}

function spawnTagged(dim, id, loc) {
  const e = dim.spawnEntity(id, loc);
  e.addTag(MOB_TAG);
  return e;
}

function trySpawnNear(player) {
  const dim = player.dimension;
  const f = floorOf(player.location.y);
  if (f < 0) return;
  const near = dim.getEntities({ location: player.location, maxDistance: 40, tags: [MOB_TAG] }).length;
  if (near >= CFG.cap[f]) return;
  const prx = roomOf(player.location.x), prz = roomOf(player.location.z);
  const rx = prx + Math.floor(Math.random() * 7) - 3, rz = prz + Math.floor(Math.random() * 7) - 3;
  if (rx === prx && rz === prz) return;
  const type = roomType(seed(), f, rx, rz);
  if (type === "vestibulo" || type === "arena") return;
  const mob = pickMob(f);
  const y = FLOORS[f] + 1;
  const count = mob.grupo[0] + Math.floor(Math.random() * (mob.grupo[1] - mob.grupo[0] + 1));
  for (let i = 0; i < count; i++) {
    const x = inner0(rx) + 1 + Math.floor(Math.random() * 8), z = inner0(rz) + 1 + Math.floor(Math.random() * 8);
    if (!airColumn(dim, x, y, z, mob.alto)) continue;
    try {
      spawnTagged(dim, mob.id, { x: x + 0.5, y, z: z + 0.5 });
    } catch {}
  }
}

system.runInterval(() => {
  for (const p of playersHere()) {
    if (Math.random() < CFG.spawnChance) {
      try {
        trySpawnNear(p);
      } catch {}
    }
  }
}, CFG.spawnInterval);

// Only the dungeon decides what appears here: other mobs are removed, except
// those of a spawn egg or born next to a dungeon monster (summons, split slimes).
let eggUntil = 0;
world.afterEvents.playerInteractWithBlock?.subscribe(({ itemStack }) => {
  if (itemStack?.typeId.endsWith("_spawn_egg")) eggUntil = now() + 5;
});
world.afterEvents.entitySpawn.subscribe(({ entity }) => {
  try {
    if (entity.dimension.id !== DIM || entity.hasTag(MOB_TAG) || !isMob(entity) || now() <= eggUntil) return;
    if (entity.dimension.getEntities({ location: entity.location, maxDistance: 6, tags: [MOB_TAG] }).length) {
      entity.addTag(MOB_TAG);
      return;
    }
    entity.remove();
  } catch {}
});

// ------------------------------------------------------------ mutant abilities
const PROP = "abismo:accion";
const state = new Map(); // entity id -> next tick its ability is ready

function setAction(e, v) {
  try {
    e.setProperty(PROP, v);
  } catch {}
}

function nearestPlayer(e, max) {
  let best = null, bd = max;
  for (const p of e.dimension.getPlayers({ location: e.location, maxDistance: max })) {
    const gm = p.getGameMode?.();
    if (gm === "Creative" || gm === "Spectator" || gm === "creative" || gm === "spectator") continue;
    const d = Math.hypot(p.location.x - e.location.x, p.location.z - e.location.z);
    if (d <= bd) { best = p; bd = d; }
  }
  return best ? { p: best, d: bd } : null;
}

function knock(p, from, push, lift) {
  const dx = p.location.x - from.x, dz = p.location.z - from.z, l = Math.hypot(dx, dz) || 1;
  try {
    p.applyKnockback({ x: (dx / l) * push, z: (dz / l) * push }, lift);
  } catch {
    try {
      p.applyKnockback(dx / l, dz / l, push, lift);
    } catch {}
  }
}

function slam(e, radius, damage) {
  const loc = e.location, dim = e.dimension;
  dim.spawnParticle("minecraft:large_explosion", { x: loc.x, y: loc.y + 0.3, z: loc.z });
  for (const p of dim.getPlayers({ location: loc, maxDistance: radius })) {
    try {
      p.applyDamage(damage, { cause: "entityAttack", damagingEntity: e });
    } catch {}
    knock(p, loc, 1.6, 0.6);
  }
}

const ABILITIES = {
  [CFG.ids.zombi]: (e, t) => {
    const n = nearestPlayer(e, 4.5);
    if (!n) return;
    setAction(e, 1);
    later(14, () => e.isValid && slam(e, 5, CFG.slam.zombi));
    later(24, () => e.isValid && setAction(e, 0));
    state.set(e.id, t + 120);
  },
  [CFG.ids.creeper]: (e, t) => {
    const n = nearestPlayer(e, 3.5);
    if (!n) return;
    setAction(e, 1);
    e.dimension.playSound("random.fuse", e.location, { volume: 1, pitch: 0.6 });
    later(28, () => {
      if (!e.isValid) return;
      e.dimension.createExplosion(e.location, CFG.blast, { breaksBlocks: false, causesFire: false, source: e });
      setAction(e, 0);
    });
    state.set(e.id, t + 140);
  },
  [CFG.ids.arana]: (e, t) => {
    const n = nearestPlayer(e, 12);
    if (!n || n.d < 4) return;
    setAction(e, 1);
    const dx = n.p.location.x - e.location.x, dz = n.p.location.z - e.location.z;
    later(5, () => e.isValid && e.applyImpulse({ x: (dx / n.d) * 1.1, y: 0.55, z: (dz / n.d) * 1.1 }));
    later(16, () => e.isValid && setAction(e, 0));
    state.set(e.id, t + 80);
  },
  [CFG.ids.boss]: (e, t) => {
    const n = nearestPlayer(e, 24);
    if (!n) return;
    const s = boss.get(e.id) ?? { roar: t + 200, summon: t + 300 };
    boss.set(e.id, s);
    if (t >= s.roar) {
      setAction(e, 2);
      later(8, () => {
        e.dimension.playSound("mob.warden.roar", e.location, { volume: 2, pitch: 0.7 });
        for (const p of e.dimension.getPlayers({ location: e.location, maxDistance: 24 })) {
          p.addEffect("darkness", 160, { amplifier: 0 });
          p.addEffect("slowness", 100, { amplifier: 1 });
        }
      });
      later(40, () => e.isValid && setAction(e, 0));
      s.roar = t + 420;
      state.set(e.id, t + 60);
    } else if (t >= s.summon) {
      setAction(e, 2);
      later(20, () => {
        if (!e.isValid) return;
        for (let i = 0; i < 3; i++) {
          const a = Math.random() * Math.PI * 2;
          const id = CFG.minions[Math.floor(Math.random() * CFG.minions.length)];
          try {
            spawnTagged(e.dimension, id, { x: e.location.x + Math.cos(a) * 4, y: e.location.y + 0.5, z: e.location.z + Math.sin(a) * 4 });
          } catch {}
        }
      });
      later(40, () => e.isValid && setAction(e, 0));
      s.summon = t + 520;
      state.set(e.id, t + 60);
    } else if (n.d <= 5.5) {
      setAction(e, 1);
      later(17, () => e.isValid && slam(e, 6.5, CFG.slam.boss));
      later(28, () => e.isValid && setAction(e, 0));
      state.set(e.id, t + 120);
    }
  },
};
const boss = new Map();

system.runInterval(() => {
  const t = now();
  let dim;
  try {
    dim = abismo();
  } catch {
    return;
  }
  for (const e of dim.getEntities({ families: ["abismo_mutante"] })) {
    const fn = ABILITIES[e.typeId];
    if (!fn || (state.get(e.id) ?? 0) > t) continue;
    try {
      fn(e, t);
    } catch {}
  }
}, 5);

// ------------------------------------------------------------ boss arenas
const arenaKey = (k) => `abismo:arena:${k}`;

system.runInterval(() => {
  for (const p of playersHere()) {
    if (floorOf(p.location.y) !== 2) continue;
    const a = arenaAt(seed(), 2, roomOf(p.location.x), roomOf(p.location.z));
    if (!a || world.getDynamicProperty(arenaKey(a.key)) === 2) continue;
    const dim = p.dimension;
    const tag = `abismo_arena_${a.key}`.replace(/[:-]/g, "_");
    if (dim.getEntities({ location: { x: a.cx, y: a.y, z: a.cz }, maxDistance: 40, tags: [tag] }).length) continue;
    try {
      const b = spawnTagged(dim, CFG.ids.boss, { x: a.cx + 3, y: a.y, z: a.cz + 3 });
      b.addTag(tag);
      world.setDynamicProperty(arenaKey(a.key), 1);
      for (const q of dim.getPlayers({ location: p.location, maxDistance: 30 }))
        q.onScreenDisplay.setTitle("§3Coloso Abisal", { subtitle: "§7despierta en la arena", fadeInDuration: 10, stayDuration: 40, fadeOutDuration: 15 });
    } catch {}
  }
}, 20);

world.afterEvents.entityDie.subscribe(({ deadEntity }) => {
  try {
    if (deadEntity.typeId !== CFG.ids.boss) return;
    const tag = deadEntity.getTags().find((t) => t.startsWith("abismo_arena_"));
    if (!tag) return;
    const dim = deadEntity.dimension;
    const a = arenaAt(seed(), 2, roomOf(deadEntity.location.x), roomOf(deadEntity.location.z));
    if (a) {
      world.setDynamicProperty(arenaKey(a.key), 2);
      // the reward: a chest next to the central pillar
      const x = Math.floor(a.cx) + 2, z = Math.floor(a.cz);
      const block = dim.getBlock({ x, y: a.y, z });
      if (block) {
        block.setPermutation(BlockPermutation.resolve("minecraft:chest"));
        fillChest(block, CFG.bossChest);
      }
    }
    for (const p of dim.getPlayers({ location: deadEntity.location, maxDistance: 40 }))
      p.onScreenDisplay.setTitle("§bColoso derrotado", { subtitle: "§7la arena guarda su tesoro", fadeInDuration: 10, stayDuration: 50, fadeOutDuration: 20 });
  } catch {}
});

// ------------------------------------------------------------ floor names
const lastFloor = new Map();
system.runInterval(() => {
  for (const p of playersHere()) {
    const f = floorOf(p.location.y);
    if (f < 0 || lastFloor.get(p.id) === f) continue;
    lastFloor.set(p.id, f);
    p.onScreenDisplay.setActionBar(`§7${CFG.floorNames[f]}`);
  }
}, 20);

// ------------------------------------------------------------ the key
const traveling = new Set();

async function teleportLoaded(player, dim, loc, id) {
  const ok = await loadArea(dim, id, { x: loc.x - 4, y: 0, z: loc.z - 4 }, { x: loc.x + 4, y: 0, z: loc.z + 4 });
  player.teleport(loc, { dimension: dim });
  if (ok) later(100, () => dropArea(id));
}

async function enter(player) {
  const here = player.location;
  player.setDynamicProperty("abismo:back", JSON.stringify({ dim: player.dimension.id, x: here.x, y: here.y, z: here.z }));
  player.onScreenDisplay.setActionBar("§3La llave gira en la oscuridad...");
  await generateRegion(0, 0);
  await teleportLoaded(player, abismo(), SPAWN, areaId("in", player.id));
  player.onScreenDisplay.setTitle("§3Mazmorras del Abismo", { subtitle: "§7Piso 1", fadeInDuration: 10, stayDuration: 50, fadeOutDuration: 20 });
  player.playSound("ambient.cave", { volume: 1 });
}

async function leave(player) {
  let back = null;
  try {
    back = JSON.parse(player.getDynamicProperty("abismo:back") ?? "null");
  } catch {}
  if (!back || back.dim === DIM) {
    const spawn = world.getDefaultSpawnLocation();
    const dim = world.getDimension("minecraft:overworld");
    const id = areaId("out", player.id);
    const loc = { x: spawn.x + 0.5, y: 0, z: spawn.z + 0.5 };
    const ok = await loadArea(dim, id, { x: loc.x - 4, y: 0, z: loc.z - 4 }, { x: loc.x + 4, y: 0, z: loc.z + 4 });
    const top = dim.getTopmostBlock({ x: loc.x, z: loc.z });
    loc.y = top ? top.y + 1 : 100;
    player.teleport(loc, { dimension: dim });
    if (ok) later(100, () => dropArea(id));
  } else {
    await teleportLoaded(player, world.getDimension(back.dim), { x: back.x, y: back.y, z: back.z }, areaId("out", player.id));
  }
  player.playSound("ambient.cave", { volume: 1 });
}

world.afterEvents.itemUse.subscribe(({ source: player, itemStack }) => {
  if (itemStack?.typeId !== CFG.key || player?.typeId !== "minecraft:player" || traveling.has(player.id)) return;
  traveling.add(player.id);
  const go = player.dimension.id === DIM ? leave(player) : enter(player);
  go.catch((e) => console.warn(`[ABISMO] viaje fallido: ${e}`)).finally(() => traveling.delete(player.id));
});
